rules.output:
{
  "Role": {
    "RoleName": "github-deploy-role",
    "Arn": "arn:aws:iam::111122223333:role/github-deploy-role",
    "Description": "Deploy role for GitHub Actions (OIDC migration, ticket SEC-2210)",
    "AssumeRolePolicyDocument": {
      "Version": "2012-10-17",
      "Statement": [
        {
          "Effect": "Allow",
          "Principal": {
            "Federated": "arn:aws:iam::111122223333:oidc-provider/token.actions.githubusercontent.com"
          },
          "Action": "sts:AssumeRoleWithWebIdentity",
          "Condition": {
            "StringLike": {
              "token.actions.githubusercontent.com:sub": "repo:acme-corp/*"
            }
          }
        }
      ]
    }
  }
}
